import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BZk_B2cc.js";const u=JSON.parse('{"title":"F4: Dual Persona Identity & Token Blacklisting","description":"","frontmatter":{},"headers":[],"relativePath":"features/F4-dual-persona-jwt-auth.md","filePath":"features/F4-dual-persona-jwt-auth.md"}'),n={name:"features/F4-dual-persona-jwt-auth.md"};function o(r,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="f4-dual-persona-identity-token-blacklisting" tabindex="-1">F4: Dual Persona Identity &amp; Token Blacklisting <a class="header-anchor" href="#f4-dual-persona-identity-token-blacklisting" aria-label="Permalink to &quot;F4: Dual Persona Identity &amp; Token Blacklisting&quot;">​</a></h1><h2 id="_1-description-security-posture" tabindex="-1">1. Description &amp; Security Posture <a class="header-anchor" href="#_1-description-security-posture" aria-label="Permalink to &quot;1. Description &amp; Security Posture&quot;">​</a></h2><p>The application enforces strict separation between Riders and Captains (<code>backend/models/user.model.js</code> vs <code>captain.model.js</code>). Authentication tokens are signed using HS256 JWTs. When a user logs out, their token is saved to a <code>blacklistTokens</code> collection with an automated MongoDB TTL index, preventing replay attacks.</p><h2 id="_2-token-revocation-diagram" tabindex="-1">2. Token Revocation Diagram <a class="header-anchor" href="#_2-token-revocation-diagram" aria-label="Permalink to &quot;2. Token Revocation Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LogoutReq[User / Captain Calls /logout] --&gt; Extract[Extract Bearer JWT Token]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Extract --&gt; Blacklist[Save to blacklistTokens Collection]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Blacklist --&gt; TTL[MongoDB TTL Index: Auto-Deletes after 24h]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AuthMW[Future Requests with Token] --&gt; CheckBL{Token in Blacklist?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CheckBL --&gt;|Yes| Reject[401 Unauthorized: Token Revoked]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CheckBL --&gt;|No| Allow[Proceed to Controller]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;I architected a dual-persona authentication system that completely segregates rider accounts from commercial driver profiles. Passwords for both roles are hashed with bcrypt using 10 salt rounds. For session management, I implemented a robust token revocation mechanism: upon logout, the JWT is stored in a MongoDB <code>blacklistTokens</code> collection equipped with a Time-To-Live (TTL) index set to 24 hours. The authentication middleware checks incoming tokens against this blacklist before decoding, ensuring that logged-out tokens cannot be replayed even if intercepted.&quot;</p>`,7)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
